":"pdfgear","novelty_score":null,"quality_score":null,"editorial_note":"Compare native page organization and PDF extraction. Reordering is documented as not undoable. AI/cloud privacy is separate; no full Acrobat or tested export-fidelity guarantee.","escape_route_id":"4b64f6fe-e76a-44a4-8f5a-684ab9b2b717","relevance_score":null,"constraint_fit_score":null}],"where":"escape_route_id='4b64f6fe-e76a-44a4-8f5a-684ab9b2b717'::uuid OR product_id IN ('ea5f6f15-62e7-465d-a9a8-90d788a4fe00'::uuid,'f17d436b-6419-40bc-88ab-d9e68432970d'::uuid,'fa72cfe7-2276-43ff-b352-8d4d26c90d65'::uuid)"},{"table":"attributes","rows":[{"id":"f540baaf-959c-485b-a65b-68c2b072841e","name":"AI Optional","slug":"ai-optional","category":"ai","created_at":"2026-10-06T02:49:38.03521+00:00","updated_at":"2026-10-06T02:49:38.03521+00:00","value_type":"boolean","description":"Core product workflows remain usable without enabling, purchasing, or depending on AI functionality. Integrated AI or optional AI plugins do not disqualify a product; evidence must support the non-AI core workflow."},{"id":"7f2af8c8-8aee-4d54-a93a-46d77a3ead17","name":"Free Core Use","slug":"free-core-use","category":"pricing","created_at":"2026-10-06T02:49:38.03521+00:00","updated_at":"2026-10-06T02:49:38.03521+00:00","value_type":"boolean","description":"A meaningful core product workflow is available without a recurring software fee."},{"id":"b4f5b4a4-87fe-4df9-86de-fd65fae5092d","name":"Local First","slug":"local-first","category":"data_control","created_at":"2026-10-06T02:49:38.03521+00:00","updated_at":"2026-10-06T02:49:38.03521+00:00","value_type":"boolean","description":"Primary data or application workflow is designed around local device storage or local-first operation."},{"id":"496d6370-cf03-4842-b0e3-22c307613b97","name":"No Subscription","slug":"no-subscription","category":"pricing","created_at":"2026-10-07T09:58:41.404192+00:00","updated_at":"2026-10-07T09:58:41.404192+00:00","value_type":"boolean","description":"The named edition supports the stated meaningful core workflow without a mandatory recurring software payment. Free and perpetual paid editions may qualify; trials do not. Optional sync, AI, cloud, maintenance and paid upgrades must be disclosed."},{"id":"cf8b0015-81e0-440b-b7d6-281ae28c43d4","name":"Open Source","slug":"open-source","category":"licensing","created_at":"2026-10-06T02:49:38.03521+00:00","updated_at":"2026-10-06T02:49:38.03521+00:00","value_type":"boolean","description":"The product or its core editor is distributed under an open-source license according to current official materials."},{"id":"83353c3f-3cd2-4505-8311-f722e720867c","name":"Pricing Model","slug":"pricing-model","category":"pricing","created_at":"2026-10-06T03:22:38.833862+00:00","updated_at":"2026-10-06T03:22:38.833862+00:00","value_type":"text","description":"Source-backed pricing model and relevant edition scope; excludes transient numeric prices."},{"id":"2e5f8446-3bb6-4e92-990e-d6c253d2417c","name":"Supported Platforms","slug":"supported-platforms","category":"platform","created_at":"2026-10-06T03:22:38.833862+00:00","updated_at":"2026-10-06T03:22:38.833862+00:00","value_type":"text","description":"Source-listed platforms and edition scope; an omitted platform is not a verified negative."},{"id":"18dee1eb-8a8a-45fa-b463-8487065642d9","name":"Trade-Off Summary","slug":"trade-off-summary","category":"workflow","created_at":"2026-10-06T03:22:38.833862+00:00","updated_at":"2026-10-06T03:22:38.833862+00:00","value_type":"text","description":"Evidence-backed restrictions or explicitly provisional editorial interpretation, with confidence status."},{"id":"2d9835d9-4aa0-4fb3-93fa-2c98d4f890c4","name":"Works Offline","slug":"works-offline","category":"offline","created_at":"2026-10-06T02:49:38.03521+00:00","updated_at":"2026-10-06T02:49:38.03521+00:00","value_type":"boolean","description":"Core work remains available without an internet connection."}],"where":"id IN ('f540baaf-959c-485b-a65b-68c2b072841e'::uuid,'7f2af8c8-8aee-4d54-a93a-46d77a3ead17'::uuid,'b4f5b4a4-87fe-4df9-86de-fd65fae5092d'::uuid,'496d6370-cf03-4842-b0e3-22c307613b97'::uuid,'cf8b0015-81e0-440b-b7d6-281ae28c43d4'::uuid,'83353c3f-3cd2-4505-8311-f722e720867c'::uuid,'2e5f8446-3bb6-4e92-990e-d6c253d2417c'::uuid,'18dee1eb-8a8a-45fa-b463-8487065642d9'::uuid,'2d9835d9-4aa0-4fb3-93fa-2c98d4f890c4'::uuid)"},{"table":"anchors","rows":[{"id":"4e54b828-4645-4d33-91db-d0bb743fcc76","name":"Adobe / PDF","slug":"adobe-pdf","created_at":"2026-10-06T03:23:43.673301+00:00","updated_at":"2026-10-06T03:23:43.673301+00:00","description":"Acrobat-style PDF reading, editing, conversion, and document-tool ecosystem; feature parity is not implied."}],"where":"id IN ('4e54b828-4645-4d33-91db-d0bb743fcc76'::uuid)"}],"published":["2do","affine","anytype","appflowy","gimp","joplin","krita","obsidian","omnifocus","paint-net","simplenote","things"],"routes":["notion-alternatives-without-ai","offline-notion-alternatives","photoshop-alternatives-without-a-subscription","simple-notion-alternatives","todoist-alternatives-with-a-one-time-purchase"],"description":"Compare Windows personal PDF page reordering, permanent rotation, removal and extraction, with PDF output, in licensed PDF-XChange Editor, PDF24 Creator and the current free PDFgear offer. This covers page organization, not complete Acrobat text editing, signatures or secure redaction. Edition, maintenance and AI/cloud limits differ."}$pdf_data$::jsonb; op jsonb; expected jsonb; actual jsonb;
BEGIN
 SET LOCAL lock_timeout='10s';
 PERFORM pg_advisory_xact_lock(7232003);
 LOCK TABLE software_discovery.products, software_discovery.product_attributes, software_discovery.product_anchors, software_discovery.product_problems, software_discovery.product_audiences, software_discovery.product_attribute_evidence, software_discovery.product_anchor_evidence, software_discovery.product_problem_evidence, software_discovery.product_audience_evidence, software_discovery.claim_evidence, software_discovery.evidence_sources, software_discovery.escape_routes, software_discovery.escape_route_products, software_discovery.attributes, software_discovery.anchors IN SHARE ROW EXCLUSIVE MODE;
 IF coalesce((SELECT jsonb_agg(slug ORDER BY slug) FROM software_discovery.products WHERE status='published'),'[]'::jsonb)<>data->'published' OR coalesce((SELECT jsonb_agg(slug ORDER BY slug) FROM software_discovery.escape_routes WHERE status='published' AND editorially_approved),'[]'::jsonb)<>data->'routes' THEN RAISE EXCEPTION 'PR5.33 publication state drift or repeated apply; fresh preflight required'; END IF;
 IF NOT has_function_privilege('anon','software_discovery.product_discovery_page(text)','EXECUTE') OR has_table_privilege('anon','software_discovery.claim_evidence','SELECT') THEN RAISE EXCEPTION 'PR5.33 anonymous evidence boundary drift'; END IF;
 FOR op IN SELECT value FROM jsonb_array_elements(data->'guards') LOOP
  EXECUTE format('SELECT coalesce(jsonb_agg(j ORDER BY j::text),''[]''::jsonb) FROM (SELECT to_jsonb(jsonb_populate_record(NULL::software_discovery.%I,r))-''created_at''-''updated_at'' j FROM jsonb_array_elements($1) r) x',op->>'table') INTO expected USING op->'rows';
  EXECUTE format('SELECT coalesce(jsonb_agg(j ORDER BY j::text),''[]''::jsonb) FROM (SELECT to_jsonb(t)-''created_at''-''updated_at'' j FROM software_discovery.%I t WHERE %s) x',op->>'table',op->>'where') INTO actual;
  IF expected<>actual THEN RAISE EXCEPTION 'PR5.33 stored checkpoint drift: %',op->>'table'; END IF;
 END LOOP;
 UPDATE software_discovery.products SET status='published' WHERE id IN ('ea5f6f15-62e7-465d-a9a8-90d788a4fe00'::uuid,'f17d436b-6419-40bc-88ab-d9e68432970d'::uuid,'fa72cfe7-2276-43ff-b352-8d4d26c90d65'::uuid);
 UPDATE software_discovery.escape_routes SET status='published',editorially_approved=true,description=data->>'description' WHERE id='4b64f6fe-e76a-44a4-8f5a-684ab9b2b717'::uuid;
 IF (SELECT count(*) FROM software_discovery.products WHERE status='published')<>15 OR (SELECT count(*) FROM software_discovery.escape_routes WHERE status='published' AND editorially_approved)<>6 THEN RAISE EXCEPTION 'PR5.33 post-publication count mismatch'; END IF;
 IF EXISTS(SELECT 1 FROM software_discovery.products WHERE id IN ('ea5f6f15-62e7-465d-a9a8-90d788a4fe00'::uuid,'f17d436b-6419-40bc-88ab-d9e68432970d'::uuid,'fa72cfe7-2276-43ff-b352-8d4d26c90d65'::uuid) AND software_discovery.product_discovery_page(slug) IS NULL) THEN RAISE EXCEPTION 'PR5.33 public product projection missing'; END IF;
 -- Owner-approved apply persists.
EXCEPTION WHEN SQLSTATE 'ZSR01' THEN
 RAISE NOTICE 'PDF publication rehearsal rolled back; no changes persisted';
END $pdf_publish$;
